float musicalAccent(float value) {
 float activity=vrchReadSignal(0)+vrchReadSignal(1)+vrchReadSignal(2);
 float crisp=smoothstep(.02,.18,vrchReadSignal(2));
 return smoothstep(.005,.25,value)*mix(1.0,.12+.88*crisp,step(.001,activity));
}

float orbitHash(vec2 p) {return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
void mainImage(out vec4 fragColor,in vec2 fragCoord) {
 vec2 p=(2.0*fragCoord-iResolution.xy)/iResolution.y;
 p*=max(1.0,1.24*iResolution.y/iResolution.x);
 float phase=vrchPhase_speed(),hit=musicalAccent(uParam_accent);
 float turn=.32+.10*sin(phase*.21);
 p=mat2(cos(turn),-sin(turn),sin(turn),cos(turn))*p;
 p.y/=uParam_tilt;
 float r=length(p),a=atan(p.y,p.x);
 vec3 color=vec3(.002,.004,.012);
 for(int i=0;i<3;i++) {
  float z=float(i),radius=uParam_radius+.035*sin(a*3.0+phase*.25+z);
  float around=a/6.2831853+.5;
  vec2 g=vec2(around*uParam_density+phase*(.55+z*.13),(r-radius)/uParam_volume*9.0+z*7.31);
  vec2 id=floor(g),local=fract(g)-.5;
  id.x=mod(id.x,uParam_density);
  vec2 random=vec2(orbitHash(id+z*17.0),orbitHash(id+vec2(11.0,23.0)+z*19.0));
  local-=(random-.5)*.4;
  float dotSize=.19+.10*random.x;
  float point=exp(-dot(local,local)/(dotSize*dotSize));
  float body=exp(-pow(abs((r-radius)/uParam_volume),2.0)*2.6);
  float depth=.33+.67*(.5-.5*sin(a));
  vec3 hue=mix(vec3(.065,.14,.55),uParam_color.rgb,.5+.5*cos(a+phase*.17));
  color+=hue*point*body*(.34+depth*uParam_light)*(1.0+hit*depth*.55)/(1.0+z*.4);
 }
 float halo=exp(-pow(abs((r-uParam_radius)/(uParam_volume*1.25)),2.0))* .018;
 color+=uParam_color.rgb*halo;
 fragColor=vec4(1.0-exp(-color*1.55),1.0);
}
